/**
 * Async_ssl C primitives — OpenSSL bindings under the
 * [async_ssl_stub_*] prefix, generated by [ctypes] from the
 * [ffi_bindings.ml] schema.
 *
 * ### Stubbing strategy
 *
 * We do NOT implement OpenSSL. Almost every [async_ssl_stub_*]
 * primitive is intentionally NOT in stubs.json and falls through
 * to the auto-generated "primitive not implemented" stub which
 * throws [CamlException(Failure)].
 *
 * The stubs in this file are DELIBERATE STUBS with elided
 * functionality — they exist solely to let module init complete
 * past eager calls that would otherwise abort the bytecode load.
 * Each stub:
 *   - returns a value that lets module init bind a constant or
 *     pass through a feature-detection check;
 *   - performs no real cryptography, no I/O;
 *   - documents the OCaml call site that drove the requirement.
 *
 * Anything past init that actually tries to perform SSL —
 * connect, encrypt, verify — will hit the auto-generated throw.
 * That's by design: this backend doesn't speak TLS, and we want
 * the failure to point at the real call rather than silently
 * succeed and leak plaintext.
 */
public final class AsyncSsl {
    private AsyncSsl() {}

    // === DELIBERATE STUB: OpenSSL OID lookup ==========================
    // [ffi__library_must_be_initialized.ml:350-353] eagerly binds
    // curve NIDs at module load:
    //   let secp384r1  = of_string "secp384r1"
    //   let secp521r1  = of_string "secp521r1"
    //   let prime256v1 = of_string "prime256v1"
    // where [of_string = Bindings.ASN1_object.txt2nid] — a thin wrapper
    // around the OpenSSL [OBJ_txt2nid] C function. Returning [1] (any
    // nonzero int) lets the constants bind; downstream uses by the
    // caller's
    // SSL paths will fail when they attempt a real handshake.
    public static long OBJ_txt2nid(Object fatptr) { return 1L; }
}
